-- ============================================================
-- Lumorius — Expanded Demo Knowledge Graph
-- Adds connected sample data to INMARTECH LLC (Demo).
-- Safe to rerun: deterministic UUIDs are upserted by primary key.
-- Development/demo data only; do not run against production.
-- ============================================================

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM organizations
    WHERE id = '00000000-0000-0000-0000-000000000001'::uuid
  ) THEN
    RAISE EXCEPTION 'Demo organization is missing. Run 002_demo_data.sql first.';
  END IF;
END $$;

